// Normalize Writer Input
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Accept semantic_workflow_output_package_v4_multilingual_compact.
// - Expand final_semantic_rows into one item per keyword row.
// - Preserve language metadata for all writer/research/audit/rewrite nodes.
// - Normalize field names for Yehor_content_plan_writer.
// - Preserve top-level company / onboarding / package metadata.
// - Create legacy-compatible serp_data from serp_context.

const items = $input.all();

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function cleanOrNull(value) {
  const s = clean(value);
  return s || null;
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function toNumOrNull(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function getLanguageInfo(row = {}, pkg = {}) {
  const contentPlanLanguage =
    firstNonEmpty(
      row.content_plan_language,
      pkg.content_plan_language,
      pkg.language?.content_plan_language
    ) || 'English';

  const contentPlanLanguageCode =
    firstNonEmpty(
      row.content_plan_language_code,
      pkg.content_plan_language_code,
      pkg.language?.content_plan_language_code,
      row.planner_language_scope,
      pkg.planner_language_scope,
      row.serper_hl,
      pkg.serper_hl
    ) || 'en';

  const googleAdsLanguage =
    firstNonEmpty(
      row.google_ads_language,
      pkg.google_ads_language,
      pkg.language?.google_ads_language,
      row.language,
      pkg.language
    ) || 'languageConstants/1000';

  return {
    content_plan_language: contentPlanLanguage,
    content_plan_language_code: contentPlanLanguageCode,
    content_plan_language_key:
      firstNonEmpty(
        row.content_plan_language_key,
        pkg.content_plan_language_key,
        pkg.language?.content_plan_language_key
      ) || contentPlanLanguage.toLowerCase(),

    google_ads_language: googleAdsLanguage,
    google_ads_language_id:
      firstNonEmpty(
        row.google_ads_language_id,
        pkg.google_ads_language_id,
        pkg.language?.google_ads_language_id,
        googleAdsLanguage.replace(/^languageConstants\//, '')
      ) || '1000',
    google_ads_language_code:
      firstNonEmpty(
        row.google_ads_language_code,
        pkg.google_ads_language_code,
        pkg.language?.google_ads_language_code,
        contentPlanLanguageCode
      ) || contentPlanLanguageCode,

    planner_language_scope:
      firstNonEmpty(
        row.planner_language_scope,
        pkg.planner_language_scope,
        pkg.language?.planner_language_scope,
        contentPlanLanguageCode
      ) || contentPlanLanguageCode,

    serper_hl:
      firstNonEmpty(
        row.serper_hl,
        pkg.serper_hl,
        pkg.language?.serper_hl,
        contentPlanLanguageCode
      ) || contentPlanLanguageCode,

    serper_gl:
      firstNonEmpty(
        row.serper_gl,
        pkg.serper_gl,
        pkg.language?.serper_gl
      ),

    language: googleAdsLanguage,
  };
}

function normalizeSerpData(row) {
  const serpContext = row.serp_context || row.serpContext || null;

  if (!serpContext) {
    return {
      organic: [],
      peopleAlsoAsk: [],
      relatedSearches: [],
    };
  }

  const topResults = Array.isArray(serpContext.top_results)
    ? serpContext.top_results
    : [];

  const peopleAlsoAsk = Array.isArray(serpContext.people_also_ask)
    ? serpContext.people_also_ask
    : [];

  const relatedSearches = Array.isArray(serpContext.related_searches)
    ? serpContext.related_searches
    : [];

  return {
    organic: topResults.map((r, idx) => ({
      position: r.position ?? idx + 1,
      title: r.title || '',
      link: r.link || '',
      snippet: r.snippet || '',
    })),
    peopleAlsoAsk: peopleAlsoAsk.map(q => ({
      question: typeof q === 'string' ? q : (q?.question || ''),
    })),
    relatedSearches: relatedSearches.map(q => ({
      query: typeof q === 'string' ? q : (q?.query || ''),
    })),
  };
}

const output = [];

for (const item of items) {
  const pkg = item.json || {};

  const packageRows = Array.isArray(pkg.final_semantic_rows)
    ? pkg.final_semantic_rows
    : [];

  const sourceRows = packageRows.length ? packageRows : [pkg];

  for (const row of sourceRows) {
    const languageInfo = getLanguageInfo(row, pkg);

    const companyName =
      cleanOrNull(row.company_name) ||
      cleanOrNull(row.client_name) ||
      cleanOrNull(pkg.company_name) ||
      cleanOrNull(pkg.client_name);

    const clientUrl =
      cleanOrNull(row.client_url) ||
      cleanOrNull(pkg.client_url);

    const semantic1 =
      cleanOrNull(row.semantic_1_keyword) ||
      cleanOrNull(row.semantic_1);

    const semantic2 =
      cleanOrNull(row.semantic_2_keyword) ||
      cleanOrNull(row.semantic_2);

    output.push({
      json: {
        payload_type: cleanOrNull(pkg.payload_type),
        execution_id: cleanOrNull(row.execution_id || pkg.execution_id),
        generated_at: cleanOrNull(pkg.generated_at),

        callback_url: cleanOrNull(row.callback_url || pkg.callback_url),
        taskId: cleanOrNull(row.taskId || pkg.taskId),
        brandId: cleanOrNull(row.brandId || pkg.brandId),
        userId: cleanOrNull(row.userId || pkg.userId),

        spreadsheet_id: cleanOrNull(row.spreadsheet_id || pkg.spreadsheet_id),
        spreadsheet_url: cleanOrNull(row.spreadsheet_url || pkg.spreadsheet_url),
        selected_sheet_id: cleanOrNull(row.selected_sheet_id || pkg.selected_sheet_id),
        selected_sheet_url: cleanOrNull(row.selected_sheet_url || pkg.selected_sheet_url),
        selected_sheet_tab_name: cleanOrNull(row.selected_sheet_tab_name || pkg.selected_sheet_tab_name),

        company_name: companyName,
        client_name: companyName,
        client_url: clientUrl,

        company_context: row.company_context || pkg.company_context || null,
        onboarding_overview: row.onboarding_overview ?? pkg.onboarding_overview ?? null,
        perplexity_overview: cleanOrNull(row.perplexity_overview || pkg.perplexity_overview),

        core_keyword: cleanOrNull(row.core_keyword),
        cluster_label: cleanOrNull(row.cluster_label),

        core_search_volume: toNumOrNull(row.core_search_volume),
        core_competition: cleanOrNull(row.core_competition),
        core_competition_index: toNumOrNull(row.core_competition_index),
        core_yoy_6_v6: toNumOrNull(row.core_yoy_6_v6),

        semantic_1_keyword: semantic1,
        semantic_1: semantic1,
        semantic_1_reason: cleanOrNull(row.semantic_1_reason || row.semantic_1_type),
        semantic_1_type: cleanOrNull(row.semantic_1_type),
        semantic_1_search_volume: toNumOrNull(row.semantic_1_search_volume),
        semantic_1_competition_index: toNumOrNull(row.semantic_1_competition_index),
        semantic_1_yoy_6_v6: toNumOrNull(row.semantic_1_yoy_6_v6),

        semantic_2_keyword: semantic2,
        semantic_2: semantic2,
        semantic_2_reason: cleanOrNull(row.semantic_2_reason || row.semantic_2_type),
        semantic_2_type: cleanOrNull(row.semantic_2_type),
        semantic_2_search_volume: toNumOrNull(row.semantic_2_search_volume),
        semantic_2_competition_index: toNumOrNull(row.semantic_2_competition_index),
        semantic_2_yoy_6_v6: toNumOrNull(row.semantic_2_yoy_6_v6),

        serp_context: row.serp_context || null,
        serp_data: normalizeSerpData(row),
        serp_source: cleanOrNull(row.serp_source),
        serp_analyzed_at: cleanOrNull(row.serp_analyzed_at),

        semantic_selected_at: cleanOrNull(row.semantic_selected_at),
        final_semantic_ready: Boolean(row.final_semantic_ready),

        content_plan_language: languageInfo.content_plan_language,
        content_plan_language_code: languageInfo.content_plan_language_code,
        content_plan_language_key: languageInfo.content_plan_language_key,
        google_ads_language: languageInfo.google_ads_language,
        google_ads_language_id: languageInfo.google_ads_language_id,
        google_ads_language_code: languageInfo.google_ads_language_code,
        planner_language_scope: languageInfo.planner_language_scope,
        serper_hl: languageInfo.serper_hl,
        serper_gl: languageInfo.serper_gl,
        language: languageInfo.language,

        source_counts: pkg.source_counts || null,
      },
    });
  }
}

if (!output.length) {
  throw new Error('Normalize Writer Input: no usable rows found.');
}

return output;

// Filter Output Fields
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Keep final 6 visible content plan fields.
// - Preserve hidden metadata for callback / downstream package.
// - Preserve language metadata.
// - Do not add extra visible Google Sheet columns downstream.

const items = $input.all();

function firstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

const trigger = firstJson('When Executed by Another Workflow');
const normalizeWriter = firstJson('Normalize Writer Input');

const callbackUrl = firstNonEmpty(trigger.callback_url, normalizeWriter.callback_url);
const taskId = firstNonEmpty(trigger.taskId, normalizeWriter.taskId);
const brandId = firstNonEmpty(trigger.brandId, normalizeWriter.brandId);
const userId = firstNonEmpty(trigger.userId, normalizeWriter.userId);

const clientName =
  firstNonEmpty(
    trigger.client_name,
    trigger.company_name,
    normalizeWriter.client_name,
    normalizeWriter.company_name
  );

const spreadsheetId =
  firstNonEmpty(
    trigger.spreadsheet_id,
    trigger.spreadsheetId,
    normalizeWriter.spreadsheet_id
  );

const spreadsheetUrl =
  firstNonEmpty(
    trigger.spreadsheet_url,
    normalizeWriter.spreadsheet_url,
    spreadsheetId ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit` : ''
  );

const languageDefaults = {
  content_plan_language: firstNonEmpty(trigger.content_plan_language, normalizeWriter.content_plan_language, 'English'),
  content_plan_language_code: firstNonEmpty(trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, trigger.serper_hl, normalizeWriter.serper_hl, 'en'),
  content_plan_language_key: firstNonEmpty(trigger.content_plan_language_key, normalizeWriter.content_plan_language_key, 'english'),
  google_ads_language: firstNonEmpty(trigger.google_ads_language, normalizeWriter.google_ads_language, trigger.language, normalizeWriter.language, 'languageConstants/1000'),
  google_ads_language_id: firstNonEmpty(trigger.google_ads_language_id, normalizeWriter.google_ads_language_id, '1000'),
  google_ads_language_code: firstNonEmpty(trigger.google_ads_language_code, normalizeWriter.google_ads_language_code, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  planner_language_scope: firstNonEmpty(trigger.planner_language_scope, normalizeWriter.planner_language_scope, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  serper_hl: firstNonEmpty(trigger.serper_hl, normalizeWriter.serper_hl, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  serper_gl: firstNonEmpty(trigger.serper_gl, normalizeWriter.serper_gl),
};

return items.map(item => {
  const d = item.json || {};

  return {
    json: {
      'Target Keyword': clean(d['Target Keyword']),
      'Semantic Keyword 1': clean(d['Semantic Keyword 1']),
      'Semantic Keyword 2': clean(d['Semantic Keyword 2']),
      'Blog Post Title': clean(d['Blog Post Title']),
      'Blog Slug': clean(d['Blog Slug']),
      'Content Brief': clean(d['Content Brief']),

      article_type: clean(d['Article Type'] || d.article_type),
      cta_rule: clean(d['CTA Rule'] || d.cta_rule),

      callback_url: callbackUrl,
      taskId,
      brandId,
      userId,
      client_name: clientName,
      spreadsheet_id: spreadsheetId,
      spreadsheet_url: spreadsheetUrl,

      content_plan_language: d.content_plan_language || languageDefaults.content_plan_language,
      content_plan_language_code: d.content_plan_language_code || languageDefaults.content_plan_language_code,
      content_plan_language_key: d.content_plan_language_key || languageDefaults.content_plan_language_key,
      google_ads_language: d.google_ads_language || languageDefaults.google_ads_language,
      google_ads_language_id: d.google_ads_language_id || languageDefaults.google_ads_language_id,
      google_ads_language_code: d.google_ads_language_code || languageDefaults.google_ads_language_code,
      planner_language_scope: d.planner_language_scope || languageDefaults.planner_language_scope,
      serper_hl: d.serper_hl || languageDefaults.serper_hl,
      serper_gl: d.serper_gl || languageDefaults.serper_gl,
      language: d.language || d.google_ads_language || languageDefaults.google_ads_language,
    },
  };
});

// Prepare Egor Callback Payload
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Send final SEO Content Plan rows to backend in Igor's requested camelCase DTO.
// - Preserve taskId, brandId, userId.
// - Keep egor-test-callback unchanged: it still sends $json.body.
// - Input is expected from Filter Output Fields.

const items = $input.all();

const DEFAULT_CALLBACK_URL = 'https://backend-production.snoika.com/n8n/webhook/keywords';

function firstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function allJson(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json || {});
  } catch (e) {
    return [];
  }
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function isValidUrl(value) {
  const s = clean(value);
  return /^https?:\/\/[^\s]+$/i.test(s);
}

function pickCallbackUrl(...values) {
  for (const value of values) {
    const s = clean(value);
    if (isValidUrl(s)) return s;
  }

  return DEFAULT_CALLBACK_URL;
}

function safeId(value) {
  const s = clean(value);
  return s || 'none';
}

function keywordKey(value) {
  return clean(value).normalize('NFC').toLowerCase();
}

const trigger = firstJson('When Executed by Another Workflow');
const normalizeWriterRows = allJson('Normalize Writer Input');
const firstRow = items[0]?.json || {};
const firstNormalizeRow = normalizeWriterRows[0] || {};

const callbackUrl = pickCallbackUrl(
  firstRow.callback_url,
  firstNormalizeRow.callback_url,
  trigger.callback_url,
  DEFAULT_CALLBACK_URL
);

const taskId = safeId(firstNonEmpty(
  firstRow.taskId,
  firstNormalizeRow.taskId,
  trigger.taskId
));

const brandId = safeId(firstNonEmpty(
  firstRow.brandId,
  firstNormalizeRow.brandId,
  trigger.brandId
));

const userId = safeId(firstNonEmpty(
  firstRow.userId,
  firstNormalizeRow.userId,
  trigger.userId
));

const clientName = firstNonEmpty(
  firstRow.client_name,
  firstRow.Client,
  firstNormalizeRow.client_name,
  firstNormalizeRow.company_name,
  trigger.client_name,
  trigger.company_name
) || 'none';

const spreadsheetId = firstNonEmpty(
  firstRow.spreadsheet_id,
  firstNormalizeRow.spreadsheet_id,
  trigger.spreadsheet_id,
  trigger.spreadsheetId
);

const spreadsheetUrl = firstNonEmpty(
  firstRow.spreadsheet_url,
  firstNormalizeRow.spreadsheet_url,
  trigger.spreadsheet_url,
  spreadsheetId ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit` : ''
);

const metaRows = [
  ...normalizeWriterRows,
  ...(Array.isArray(trigger.final_semantic_rows) ? trigger.final_semantic_rows : []),
];

const metaByKeyword = {};

for (const row of metaRows) {
  const keyword = firstNonEmpty(
    row['Target Keyword'],
    row.core_keyword,
    row.keyword
  );

  if (!keyword) continue;
  metaByKeyword[keywordKey(keyword)] = row;
}

function findMeta(row, index) {
  const keyword = firstNonEmpty(
    row['Target Keyword'],
    row.targetKeyword,
    row.core_keyword,
    row.keyword
  );

  if (keyword && metaByKeyword[keywordKey(keyword)]) {
    return metaByKeyword[keywordKey(keyword)];
  }

  return normalizeWriterRows[index] || {};
}

const keywords = items
  .map((item, index) => {
    const row = item.json || {};
    const meta = findMeta(row, index);

    const targetKeyword = firstNonEmpty(
      row.targetKeyword,
      row['Target Keyword'],
      row.core_keyword,
      meta.core_keyword,
      meta.keyword
    );

    if (!targetKeyword) return null;

    const semantic1 = firstNonEmpty(
      row['Semantic Keyword 1'],
      row.semanticKeyword1,
      row.semantic_1_keyword,
      row.semantic_1,
      meta.semantic_1_keyword,
      meta.semantic_1
    );

    const semantic2 = firstNonEmpty(
      row['Semantic Keyword 2'],
      row.semanticKeyword2,
      row.semantic_2_keyword,
      row.semantic_2,
      meta.semantic_2_keyword,
      meta.semantic_2
    );

    const semanticKeywords = [semantic1, semantic2]
      .map(clean)
      .filter(Boolean);

    return {
      targetKeyword,
      semanticKeywords,
      blogPostTitle: firstNonEmpty(
        row.blogPostTitle,
        row['Blog Post Title'],
        row.blog_post_title,
        row.title
      ) || '',
      blogSlug: firstNonEmpty(
        row.blogSlug,
        row['Blog Slug'],
        row.blog_slug,
        row.slug
      ) || '',
      contentBrief: firstNonEmpty(
        row.contentBrief,
        row['Content Brief'],
        row.content_brief,
        row.brief
      ) || '',
    };
  })
  .filter(Boolean);

if (!keywords.length) {
  throw new Error('Prepare Egor Callback Payload: no backend-ready SEO content plan rows found.');
}

return [
  {
    json: {
      callback_url: callbackUrl,

      taskId,
      brandId,
      userId,

      client_name: clientName,
      spreadsheet_id: spreadsheetId || null,
      spreadsheet_url: spreadsheetUrl || null,

      row_count: keywords.length,

      body: {
        taskId,
        brandId,
        userId,

        client_name: clientName,
        spreadsheet_id: spreadsheetId || null,
        spreadsheet_url: spreadsheetUrl || null,
        row_count: keywords.length,

        keywords,
      },
    },
  },
];

// Prepare Content Plan Sheet Package
// Type: Code node
// Mode: Run Once for All Items

const items = $input.all().map(i => i.json || {});
let trigger = {};
try {
  trigger = $('When Executed by Another Workflow').first().json || {};
} catch (e) {
  trigger = {};
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function sanitizeSheetPart(value, fallback = 'Client') {
  const s = clean(value)
    .replace(/[\\\/\?\*\[\]\:]/g, '')
    .replace(/[^\p{L}\p{N} _-]/gu, '')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '');

  return s || fallback;
}

function pad(n) {
  return String(n).padStart(2, '0');
}

const spreadsheetId =
  trigger.spreadsheet_id ||
  trigger.spreadsheetId ||
  items.find(r => r.spreadsheet_id)?.spreadsheet_id ||
  null;

if (!spreadsheetId) {
  throw new Error('Missing spreadsheet_id in When Executed by Another Workflow payload.');
}

const now = new Date();
const hh = pad(now.getHours());
const mm = pad(now.getMinutes());
const ss = pad(now.getSeconds());

const executionId = clean(trigger.execution_id || Date.now());
const clientNameRaw = clean(trigger.client_name || trigger.company_name || items[0]?.client_name || 'Client');
const clientNameSafe = sanitizeSheetPart(clientNameRaw, 'Client');

let sheetTabName = `Content_plan_${clientNameSafe}_time_${hh}_${mm}_${ss}`;

if (sheetTabName.length > 95) {
  sheetTabName = sheetTabName.slice(0, 95);
}

const headers = [
  'Target Keyword',
  'Semantic Keyword 1',
  'Semantic Keyword 2',
  'Blog Post Title',
  'Blog Slug',
  'Content Brief'
];

const rows = items.map(row => ({
  'Target Keyword': clean(row['Target Keyword']),
  'Semantic Keyword 1': clean(row['Semantic Keyword 1']),
  'Semantic Keyword 2': clean(row['Semantic Keyword 2']),
  'Blog Post Title': clean(row['Blog Post Title']),
  'Blog Slug': clean(row['Blog Slug']),
  'Content Brief': clean(row['Content Brief']),
}));

const language = {
  content_plan_language: firstNonEmpty(trigger.content_plan_language, items[0]?.content_plan_language, 'English'),
  content_plan_language_code: firstNonEmpty(trigger.content_plan_language_code, items[0]?.content_plan_language_code, trigger.serper_hl, items[0]?.serper_hl, 'en'),
  content_plan_language_key: firstNonEmpty(trigger.content_plan_language_key, items[0]?.content_plan_language_key, 'english'),
  google_ads_language: firstNonEmpty(trigger.google_ads_language, items[0]?.google_ads_language, trigger.language, items[0]?.language, 'languageConstants/1000'),
  google_ads_language_id: firstNonEmpty(trigger.google_ads_language_id, items[0]?.google_ads_language_id, '1000'),
  google_ads_language_code: firstNonEmpty(trigger.google_ads_language_code, items[0]?.google_ads_language_code, trigger.content_plan_language_code, items[0]?.content_plan_language_code, 'en'),
  planner_language_scope: firstNonEmpty(trigger.planner_language_scope, items[0]?.planner_language_scope, trigger.content_plan_language_code, items[0]?.content_plan_language_code, 'en'),
  serper_hl: firstNonEmpty(trigger.serper_hl, items[0]?.serper_hl, trigger.content_plan_language_code, items[0]?.content_plan_language_code, 'en'),
  serper_gl: firstNonEmpty(trigger.serper_gl, items[0]?.serper_gl),
};

return [{
  json: {
    spreadsheet_id: spreadsheetId,
    spreadsheet_url:
      trigger.spreadsheet_url ||
      `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`,
    selected_sheet_id: trigger.selected_sheet_id || null,
    selected_sheet_url: trigger.selected_sheet_url || '',
    selected_sheet_tab_name: trigger.selected_sheet_tab_name || '',

    client_name: clientNameRaw,
    client_name_safe: clientNameSafe,
    execution_id: executionId,
    exported_at: new Date().toISOString(),
    row_count: rows.length,
    sheet_tab_name: sheetTabName,
    headers,
    rows,

    ...language,
    language: language.google_ads_language,
  }
}];

const pkg = $('Prepare Content Plan Sheet Package').first().json;
const createdTab = $input.first().json || {};

const spreadsheetId = pkg.spreadsheet_id;
const sheetId =
  createdTab.sheetId ||
  createdTab.properties?.sheetId ||
  null;

if (!spreadsheetId) {
  throw new Error('Missing spreadsheet_id after tab creation.');
}

return [{
  json: {
    ...pkg,
    sheet_id: sheetId,
    sheet_url: sheetId
      ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit#gid=${sheetId}`
      : (pkg.spreadsheet_url || `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit`)
  }
}];

const pkg = $input.first().json;

return [{
  json: {
    spreadsheet_id: pkg.spreadsheet_id,
    sheet_tab_name: pkg.sheet_tab_name,
    headers: pkg.headers,
    sheet_url: pkg.sheet_url
  }
}];

const pkg = $('Restore Content Plan Package After Tab Create').first().json || {};

const rows = Array.isArray(pkg.rows) ? pkg.rows : [];

if (!rows.length) {
  throw new Error('No content plan rows found.');
}

return rows.map(row => ({
