// Build AI Content Plan Handoff Package
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Collect the full content-plan writer workflow output.
// - Preserve sheet/table info, final SEO content plan rows, keyword metadata,
//   cluster labels, metrics, audit/rewrite data, callback IDs, language metadata,
//   and ClickUp result.
// - Send one complete package into the next workflow: Ai-content-plan.
// - Google Sheet SEO content plan stays 6 visible columns.
// - AI workflow payload preserves metadata for downstream AI content planning.
// - Universal for any business type, industry, and content plan language.
//
// Important fix:
// - Selected keyword metadata MUST come from the final selected keyword rows,
//   preferably the "Final Selected Keywords" node.
// - Do NOT use "Normalize Writer Input" as the primary keyword metadata source.
//   That node can contain only workflow/input metadata and may not contain selected keywords.

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function cleanOrNull(value) {
  const s = clean(value);
  return s || null;
}

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function take(value, limit) {
  return arr(value).slice(0, limit);
}

function num(value, fallback = null) {
  if (value === null || value === undefined || value === '') return fallback;
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeKey(value) {
  return clean(value).normalize('NFC').toLowerCase();
}

function uniq(values) {
  const seen = new Set();
  const out = [];

  for (const value of arr(values)) {
    const s = clean(value);
    if (!s) continue;

    const key = s.normalize('NFC').toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    out.push(s);
  }

  return out;
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function compactText(value, maxChars = 2500) {
  const s = clean(value);
  if (!s) return '';
  return s.length > maxChars ? s.slice(0, maxChars) : s;
}

function firstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function allJson(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json || {});
  } catch (e) {
    return [];
  }
}

function safeParseJson(raw, fallback = null) {
  if (!raw) return fallback;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;

  const text = String(raw)
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const match = text.match(/\{[\s\S]*\}/);
  const candidate = match ? match[0] : text;

  try {
    return JSON.parse(candidate);
  } catch (e) {
    return fallback;
  }
}

function getAgentJson(nodeName) {
  const row = firstJson(nodeName);
  return safeParseJson(row.output || row.text || row.result || row, {});
}

function rowHasKeyword(row) {
  if (!row || typeof row !== 'object') return false;

  const meta = row.keyword_metadata || {};

  return Boolean(
    clean(
      row.core_keyword ||
      row.keyword ||
      row['Target Keyword'] ||
      row.target_keyword ||
      meta.keyword
    )
  );
}

function firstKeywordRowsSource(candidates) {
  for (const candidate of candidates) {
    const rows = arr(candidate.rows).filter(rowHasKeyword);

    if (rows.length) {
      return {
        source: candidate.source,
        rows,
      };
    }
  }

  return {
    source: 'none',
    rows: [],
  };
}

