    );

  const contentPlanLanguageCode =
    firstNonEmpty(
      ...sources.map(s => s?.content_plan_language_code),
      ...sources.map(s => s?.language?.content_plan_language_code),
      ...sources.map(s => s?.planner_language_scope),
      ...sources.map(s => s?.language?.planner_language_scope),
      ...sources.map(s => s?.serper_hl),
      ...sources.map(s => s?.language?.serper_hl),
      'en'
    );

  const googleAdsLanguage =
    firstNonEmpty(
      ...sources.map(s => s?.google_ads_language),
      ...sources.map(s => s?.language?.google_ads_language),
      ...sources.map(s => s?.language),
      'languageConstants/1000'
    );

  return {
    content_plan_language: contentPlanLanguage,
    content_plan_language_code: contentPlanLanguageCode,
    content_plan_language_key:
      firstNonEmpty(
        ...sources.map(s => s?.content_plan_language_key),
        ...sources.map(s => s?.language?.content_plan_language_key),
        contentPlanLanguage.toLowerCase()
      ),

    google_ads_language: googleAdsLanguage,
    google_ads_language_id:
      firstNonEmpty(
        ...sources.map(s => s?.google_ads_language_id),
        ...sources.map(s => s?.language?.google_ads_language_id),
        googleAdsLanguage.replace(/^languageConstants\//, ''),
        '1000'
      ),

    google_ads_language_code:
      firstNonEmpty(
        ...sources.map(s => s?.google_ads_language_code),
        ...sources.map(s => s?.language?.google_ads_language_code),
        contentPlanLanguageCode
      ),

    planner_language_scope:
      firstNonEmpty(
        ...sources.map(s => s?.planner_language_scope),
        ...sources.map(s => s?.language?.planner_language_scope),
        contentPlanLanguageCode
      ),

    serper_hl:
      firstNonEmpty(
        ...sources.map(s => s?.serper_hl),
        ...sources.map(s => s?.language?.serper_hl),
        contentPlanLanguageCode
      ),

    serper_gl:
      firstNonEmpty(
        ...sources.map(s => s?.serper_gl),
        ...sources.map(s => s?.language?.serper_gl)
      ),

    language: googleAdsLanguage,
  };
}

