parameters.jsCode:
// Parser
// Type: Code node
// Mode: Run Once for Each Item
//
// - Reads the structured agent output (7 final fields).
// - Restores locked keyword fields from Prepare Research Agent
//   (the agent is never trusted with them).
// - Derives a Unicode-safe Blog Slug from the locked keyword, since the
//   downstream audit, sheet, and callback still require a slug.
// - Emits the row shape expected by build_audit_dataset and the
//   handoff package.

const aiResponse = $json || {};

// One item per loop iteration, so .first() is the matching row.
// Do NOT use .item here: paired-item tracing across SplitInBatches
// iterations gets slower every loop and eventually hangs the node.
let originalData = {};
try {
  originalData = $('Prepare Research Agent').first().json || {};
} catch (e) {
  originalData = {};
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function slugify(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFC')
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}\s-]/gu, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

function extractJson(raw) {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (raw.output) return extractJson(raw.output);
    return raw;
  }

  const text = String(raw ?? '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const match = text.match(/\{[\s\S]*\}/);
  const candidate = match ? match[0] : text;

  return JSON.parse(candidate);
}

let aiParsed = {};
let parseFailed = false;
const aiText = aiResponse.output || aiResponse.text || aiResponse.result || JSON.stringify(aiResponse);

try {
  aiParsed = extractJson(aiText);
} catch (error) {
  aiParsed = {};
  parseFailed = true;
}

const targetKeyword = clean(originalData.core_keyword);
const semantic1 = clean(originalData.semantic_1_keyword);
const semantic2 = clean(originalData.semantic_2_keyword);

// The locked keyword is the backbone of the row: the memory, audit,
// sheet, and callback all key on it. If it is missing, the node
// reference above silently failed - fail loudly instead of producing
// a hollow row that the Memory Recorder would skip.
if (!targetKeyword) {
  throw new Error(
    "Parser: could not read the keyword row back from $('Prepare Research Agent'). " +
    "Check that a node with EXACTLY that name exists and ran in this loop iteration (rename the reference here if you renamed the node)."
  );
}

const blogTitle = clean(aiParsed['Blog Post Title']) || targetKeyword;
const articleType = clean(aiParsed['Article Type']);
const contentBrief = clean(aiParsed['Content Brief']);
const ctaRule = clean(aiParsed['CTA Rule']);
const blogSlug = slugify(targetKeyword);

const contentPlanLanguage = firstNonEmpty(originalData.content_plan_language, 'English');
const contentPlanLanguageCode = firstNonEmpty(originalData.content_plan_language_code, originalData.serper_hl, 'en');

// Keep the row lean: the agent payload and memory list are not needed
// downstream of this point.
const { previously_used_angles, previous_rows, research_agent_input, _competitor_body, ...rowBase } = originalData;

return {
  json: {
    ...rowBase,

    'Target Keyword': targetKeyword,
    'Semantic Keyword 1': semantic1,
    'Semantic Keyword 2': semantic2,
    'Blog Post Title': blogTitle,
    'Blog Slug': blogSlug,
    'Article Type': articleType,
    'Content Brief': contentBrief,
    'CTA Rule': ctaRule,

    'Client': originalData.company_name || '',
    'Cluster Name': originalData.cluster_label || '',
    'Primary Intent': 'other',
    'Stage': 'MoFu',

    article_type: articleType,
    cta_rule: ctaRule,
    unique_angle: contentBrief,
    slug_basis: blogSlug,

    content_plan_language: contentPlanLanguage,
    content_plan_language_code: contentPlanLanguageCode,

    parse_debug: {
      agent_output_parse_failed: parseFailed,
      locked_keywords_restored_from_input: true,
      slug_derived_from_locked_keyword: true,
    },
  },
};

const items = $input.all();

return items.map((item, index) => ({
  json: {
    ...item.json,
    row_id: item.json.row_id || `row_${index + 1}`,
  },
}));

const items = $input.all();

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

const first = items[0]?.json || {};

const rows = items.map(item => {
  const j = item.json || {};
  return {
    row_id: j.row_id,
    'Blog Post Title': clean(j['Blog Post Title']),
    'Content Brief': clean(j['Content Brief']),
    'CTA Rule': clean(j['CTA Rule']),
  };
});

return [{
  json: {
    target_language: clean(first.content_plan_language) || 'English',
    target_language_code: clean(first.content_plan_language_code) || 'en',
    rows,
  },
}];

const raw = $input.first().json.output;

let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = { rows: [] };
}

const verdicts = Array.isArray(parsed.rows) ? parsed.rows : [];
const wrongRowIds = verdicts
  .filter(v => v && v.language_ok === false && v.row_id)
  .map(v => String(v.row_id));

return [{
  json: {
    needs_translation: wrongRowIds.length > 0,
    wrong_row_ids: wrongRowIds,
    total_rows: verdicts.length,
  },
}];

const wrongRowIds = $input.first().json.wrong_row_ids || [];
const allRows = $('Collect Final Rows').all().map(i => i.json || {});

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

const FIELDS = ['Blog Post Title', 'Content Brief', 'CTA Rule'];

const DEEPL_TARGETS = {
  en: 'EN-GB',
  pt: 'PT-PT',
  no: 'NB',
};

const first = allRows[0] || {};
const code = clean(first.content_plan_language_code).toLowerCase() || 'en';
const targetSource = DEEPL_TARGETS[code] || code.toUpperCase();

const wrongRows = allRows.filter(r => wrongRowIds.includes(String(r.row_id)));

if (!wrongRows.length) {
  throw new Error('Translation Prep: no rows matched wrong_row_ids.');
}

const fieldNames = [];
const fieldTexts = [];

for (const row of wrongRows) {
  for (const field of FIELDS) {
    fieldNames.push(`${row.row_id}::${field}`);
    fieldTexts.push(clean(row[field]) || ' ');
  }
}

return [{
  json: {
    fieldNames,
    fieldTexts,
    targetSource,
  },
}];

const deeplResponse = $input.first().json;
const prep = $('Translation Prep').first().json;

if (!deeplResponse.translations || !Array.isArray(deeplResponse.translations)) {
  throw new Error(`DeepL response missing translations array. Response: ${JSON.stringify(deeplResponse)}`);
}
if (deeplResponse.translations.length !== prep.fieldNames.length) {
  throw new Error(`DeepL returned ${deeplResponse.translations.length} translations but expected ${prep.fieldNames.length}`);
}

const decodeEntities = (str) =>
  typeof str === 'string'
    ? str
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&#x2F;/g, '/')
    : str;

const translations = {};
prep.fieldNames.forEach((name, idx) => {
  const sep = name.indexOf('::');
  const rowId = name.slice(0, sep);
  const field = name.slice(sep + 2);
  if (!translations[rowId]) translations[rowId] = {};
  translations[rowId][field] = decodeEntities(deeplResponse.translations[idx].text).trim();
});

return [{ json: { translations } }];

const translations = $input.first().json.translations || {};
const allRows = $('Collect Final Rows').all().map(i => i.json || {});

return allRows.map(row => {
  const patch = translations[String(row.row_id)];
  if (!patch) return { json: row };
  return {
    json: {
      ...row,
      'Blog Post Title': patch['Blog Post Title'] || row['Blog Post Title'],
      'Content Brief': patch['Content Brief'] || row['Content Brief'],
      'CTA Rule': patch['CTA Rule'] || row['CTA Rule'],
      unique_angle: patch['Content Brief'] || row.unique_angle,
      cta_rule: patch['CTA Rule'] || row.cta_rule,
      _translated: true,
    },
  };
});

const rows = $('Collect Final Rows').all().map(i => i.json || {});

if (!rows.length) {
  throw new Error('Pass Rows: no rows found from Collect Final Rows.');
}

return rows.map(row => ({ json: row }));
